import sys
from itertools import combinations

def find_strings(distances):
    h12, h13, h14 = distances[0]
    h23, h24 = distances[1]
    h34 = distances[2]

    total_distances = [h12, h13, h14, h23, h24, h34]
    if max(total_distances) > sum(total_distances) // 2:
        return -1

    n = 0
    while True:
        found = False
        for s1 in product('ab', repeat=n):
            for s2 in product('ab', repeat=n):
                if hamming_distance(s1, s2) == h12:
                    for s3 in product('ab', repeat=n):
                        if hamming_distance(s1, s3) == h13 and hamming_distance(s2, s3) == h23:
                            for s4 in product('ab', repeat=n):
                                if hamming_distance(s1, s4) == h14 and hamming_distance(s2, s4) == h24 and hamming_distance(s3, s4) == h34:
                                    found = True
                                    return n, ''.join(s1), ''.join(s2), ''.join(s3), ''.join(s4)
        if found:
            break
        n += 1

def hamming_distance(s1, s2):
    return sum(c1 != c2 for c1, c2 in zip(s1, s2))

def main():
    import sys
    input = sys.stdin.read().split()
    distances = [[int(x) for x in input[:3]], [int(x) for x in input[3:5]], [int(input[5])]]
    result = find_strings(distances)
    if result == -1:
        print(-1)
    else:
        n, s1, s2, s3, s4 = result
        print(n)
        print(s1)
        print(s2)
        print(s3)
        print(s4)

if __name__ == "__main__":
    main()
